//! The W1 admission gate over `testdata/w1-admission`.
//!
//! Every cell's chart is generated by this checkout's CLI with exactly the recipe `main=` was
//! measured with ([`admission::generation_arguments`]), and the schema validates the cell's
//! values composed over the chart defaults. The recorded verdict must hold: a cell that moves away
//! from the recorded pinned-Helm class is a new failure, and a cell that moves toward it must be
//! re-recorded, so the suite always states the current main. `obligations.tsv` must list exactly
//! the cells main gets wrong, and the cells must be exactly the frozen `roster.tsv`, whose size
//! and digest are pinned here. Every composed values document must hash to the one pinned Helm
//! coalesced from the same inputs (`coalesced.tsv`). Helm does not run here; its results are
//! recorded.

use std::collections::{BTreeMap, BTreeSet};
use std::fs;
use std::path::Path;
use std::process::Command;
use std::sync::Mutex;

use color_eyre::eyre;
use helm_schema_test_support::admission::{
    self, Admission, Cell, DeclaredTypes, Suite, Verdict, classify,
};
use helm_schema_test_support::registry::PROVIDER_BUNDLE;
use helm_schema_test_support::source_digest::sha256_hex;
use serde_json::Value;
use test_util::scratch::ScratchDir;

/// The frozen roster: adding or removing a cell edits `roster.tsv` and these two constants.
const ROSTER_CELLS: usize = 1609;
const ROSTER_SHA256: &str = "851b97b5a9c694c4ae0e998b9ed35cea8c86875266723bcd1d2545614037d557";

/// Concurrent generations: each is a short CLI run over a one-template chart.
const WORKERS: usize = 4;

type Schemas = BTreeMap<(String, DeclaredTypes), Result<jsonschema::Validator, String>>;

#[test]
fn every_admission_cell_keeps_its_recorded_verdict() -> eyre::Result<()> {
    let root = test_util::workspace_testdata().join(admission::SUITE_DIR);
    let suite = admission::read_suite(&root)?;
    let roster = fs::read(root.join(admission::ROSTER))?;
    let mut failures = Vec::new();
    if sha256_hex(&roster) != ROSTER_SHA256 || suite.roster.len() != ROSTER_CELLS {
        failures.push(format!(
            "roster.tsv holds {} cells with another digest than the pinned {ROSTER_CELLS}; \
             a roster change edits ROSTER_CELLS and ROSTER_SHA256 explicitly",
            suite.roster.len()
        ));
    }
    failures.extend(suite.roster_mismatches());
    failures.extend(suite.obligation_mismatches());
    failures.extend(suite.coalesced_mismatches()?);
    let scratch = ScratchDir::new("w1-admission")?;
    let jobs: BTreeSet<(String, DeclaredTypes)> = suite
        .cells
        .iter()
        .map(|cell| (cell.chart.clone(), cell.declared_types))
        .collect();
    let schemas = generate(&root, jobs, scratch.path())?;
    let mut counts = BTreeMap::new();
    for cell in &suite.cells {
        let observed = schemas
            .get(&(cell.chart.clone(), cell.declared_types))
            .ok_or_else(|| "never generated".to_string())
            .and_then(|schema| schema.as_ref().map_err(Clone::clone))
            .and_then(|schema| verdict(&suite, cell, schema, scratch.path()));
        let observed = match observed {
            Ok(observed) => observed,
            Err(reason) => {
                failures.push(format!("{}: harness failure: {reason}", cell.id));
                continue;
            }
        };
        let outcome = classify(cell, observed);
        *counts.entry(format!("{outcome:?}")).or_insert(0_usize) += 1;
        match outcome {
            Admission::Kept => {}
            Admission::New => failures.push(format!(
                "{}: NEW failure: the schema now says {} where main={} agreed with Helm",
                cell.id,
                verdict_name(observed),
                verdict_name(cell.main)
            )),
            Admission::Closed => failures.push(format!(
                "{}: closed: the schema now agrees with Helm; record main={} for it in \
                 testdata/w1-admission and remove its obligations.tsv row (README.md, \
                 Re-recording)",
                cell.id,
                verdict_name(observed)
            )),
        }
    }
    eyre::ensure!(
        failures.is_empty(),
        "{} admission failures over {} cells ({counts:?}):\n{}",
        failures.len(),
        suite.cells.len(),
        failures.join("\n")
    );
    Ok(())
}

fn verdict_name(verdict: Verdict) -> &'static str {
    match verdict {
        Verdict::Accept => "accept",
        Verdict::Reject => "reject",
    }
}

/// Generates every (chart, mode) job with this checkout's CLI.
fn generate(
    root: &Path,
    jobs: BTreeSet<(String, DeclaredTypes)>,
    scratch: &Path,
) -> eyre::Result<Schemas> {
    let bundle = test_util::workspace_testdata().join(PROVIDER_BUNDLE);
    let queue = Mutex::new(jobs.into_iter().enumerate().collect::<Vec<_>>());
    let schemas = Mutex::new(Schemas::new());
    std::thread::scope(|scope| {
        for _ in 0..WORKERS {
            scope.spawn(|| {
                loop {
                    let next = queue.lock().map(|mut queue| queue.pop());
                    let Ok(Some((index, (chart, mode)))) = next else {
                        break;
                    };
                    let out = scratch.join(format!("schema-{index}.json"));
                    let result = generate_one(&root.join(&chart), mode, &bundle, &out, scratch);
                    if let Ok(mut schemas) = schemas.lock() {
                        schemas.insert((chart, mode), result);
                    }
                }
            });
        }
    });
    schemas
        .into_inner()
        .map_err(|_| eyre::eyre!("a generation worker panicked"))
}

fn generate_one(
    chart: &Path,
    mode: DeclaredTypes,
    bundle: &Path,
    out: &Path,
    scratch: &Path,
) -> Result<jsonschema::Validator, String> {
    let arguments: Vec<String> = admission::generation_arguments(mode)
        .into_iter()
        .map(|argument| {
            argument
                .replace("<chart>", &chart.to_string_lossy())
                .replace("<bundle>", &bundle.to_string_lossy())
                .replace("<out>", &out.to_string_lossy())
        })
        .collect();
    let output = Command::new(env!("CARGO_BIN_EXE_helm-schema"))
        .env_clear()
        .env("HOME", scratch)
        .env("XDG_CONFIG_HOME", scratch)
        .env("XDG_CACHE_HOME", scratch)
        .args(&arguments)
        .output()
        .map_err(|error| format!("spawn: {error}"))?;
    if !output.status.success() {
        return Err(format!(
            "generation failed ({}): {}",
            output.status,
            String::from_utf8_lossy(&output.stderr)
        ));
    }
    let schema: Value = fs::read(out)
        .map_err(|error| error.to_string())
        .and_then(|bytes| serde_json::from_slice(&bytes).map_err(|error| error.to_string()))?;
    jsonschema::validator_for(&schema).map_err(|error| format!("schema does not compile: {error}"))
}

/// The schema's verdict on the cell's values composed over its chart's defaults.
fn verdict(
    suite: &Suite,
    cell: &Cell,
    schema: &jsonschema::Validator,
    scratch: &Path,
) -> Result<Verdict, String> {
    let instance =
        admission::compose(suite, cell, scratch).map_err(|error| format!("{error:#}"))?;
    Ok(if schema.is_valid(&instance) {
        Verdict::Accept
    } else {
        Verdict::Reject
    })
}
